after.content:
  if (code !== 0) throw new Error(`acpx exited ${code}: ${stderr || stdout}`);
  const lines = stdout.trim().split(/\r?\n/).filter(Boolean).map((line) => JSON.parse(line));
  if (!stdout.includes("acpx-smoke-ok")) throw new Error(`acpx did not receive Agent output: ${stdout}`);
  const result = { ok: true, client: "acpx", version: "0.13.2", events: lines.length };
  if (resultPath) await writeFile(resolve(resultPath), `${JSON.stringify(result, null, 2)}\n`, "utf8");
  process.stdout.write(`${JSON.stringify(result)}\n`);
} finally {
  await new Promise((resolveClose) => provider.close(resolveClose));
  await rm(temporary, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 });
